package com.ginga.naviai.tags.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class TagResponse {
    private String name;
    private Long count;
}

package com.ginga.naviai.tags.repository;

import com.ginga.naviai.knowledge.entity.Tag;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface TagRepository extends JpaRepository<Tag, Long> {

    interface TagCountProjection {
        String getName();
        Long getCount();
    }

    @Query(value = "SELECT t.name AS name, COUNT(kt.knowledge_id) AS count " +
            "FROM tag t " +
            "JOIN knowledge_tag kt ON t.id = kt.tag_id " +
            "JOIN knowledge k ON k.id = kt.knowledge_id " +
            "WHERE k.is_deleted = false AND k.status = 'published' " +
            "GROUP BY t.name " +
            "ORDER BY COUNT(kt.knowledge_id) DESC, t.name ASC", nativeQuery = true)
    List<TagCountProjection> findTagUsageCounts();
}

package com.ginga.naviai.tags.service;

import com.ginga.naviai.tags.dto.TagResponse;

import java.util.List;

public interface TagService {
    List<TagResponse> getAllTags();
}

package com.ginga.naviai.tags.service;

import com.ginga.naviai.tags.dto.TagResponse;
import com.ginga.naviai.tags.repository.TagRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@RequiredArgsConstructor
public class TagServiceImpl implements TagService {

    private final TagRepository tagRepository;

    @Override
    @Transactional(readOnly = true)
    public List<TagResponse> getAllTags() {
        return tagRepository.findTagUsageCounts().stream()
                .map(row -> TagResponse.builder()
                        .name(row.getName())
                        .count(row.getCount())
                        .build())
                .toList();
    }
}

